.libPaths(c('/Volumes/Brain6Work/cfdr-patched-lib','/Volumes/Brain6Work/lib','/Volumes/Extreme SSD/brain6-work/exploratory-finemap-coloc-v1/Rlib',.libPaths()))
library(cfdr.pleio);library(data.table);library(Matrix)
args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1,!dir.exists(args[1]));dir.create(args[1]);refdir<-file.path(args[1],'ref');dir.create(refdir)
set.seed(534);n<-44;x<-data.table(SNP=sample(sprintf('s%03d',1:n)),CHR=rep(1:22,each=2),BP=rep(c(100,200),22),A1='A',A2='C',MAF=.2,INTERGENIC=1L);trait<-data.table(SNP=x$SNP,BETA=seq_len(n)/100,PVAL=seq_len(n)/(n+1));saveRDS(x[sample(.N)],file.path(refdir,'all_chr_perVariant.rds'))
for(chr in 1:22){ids<-x[CHR==chr,SNP];m<-Matrix(matrix(c(0,1,1,0),2),sparse=TRUE);dimnames(m)<-list(ids,ids);saveRDS(m,file.path(refdir,sprintf('chr%02d_LDpairs.rds',chr)))}
expected<-x[order(CHR,BP,SNP),SNP];out<-list()
for(k in 1:3){d<-file.path(args[1],paste0('run',k));v<-trait[sample(.N)];obj<-cfdr_pleio$new();obj$init_data(v,v,refdat=refdata_location(refdir),local_refdat_path=d,verbose=FALSE);tab<-readRDS(get_variants(obj$refdat_local));mids<-unlist(lapply(1:22,function(i)colnames(readRDS(get_chrmat(obj$refdat_local,i)))),use.names=FALSE);stopifnot(identical(tab$SNP,expected),identical(obj$trait_data$SNP,expected),identical(mids,expected));stopifnot(all.equal(obj$trait_data$BETA1,trait$BETA[match(expected,trait$SNP)]));obj$initialize_pruning_index(n_iter=10,seed=1234,verbose=FALSE);for(i in 1:22)stopifnot(all(colSums(obj$index[(2*i-1):(2*i),,drop=FALSE])==1));out[[k]]<-obj$index}
stopifnot(identical(out[[1]],out[[2]]),identical(out[[1]],out[[3]]));cat('PASS: 44 SNPs, 22 chromosomes, 3 input permutations, 10 pruning iterations; genomic rows, chromosome matrices, effects and fixed-seed indices aligned; each synthetic linked pair retained exactly one SNP.\n');cat('version',as.character(packageVersion('cfdr.pleio')),'\n');print(sessionInfo())
